     "יצירת עננים (4 דק׳). כל ילד מקבל פתק עם משפט מחשבתי, כמו \"אני לא טוב בכלום\", \"אף אחד לא רוצה לשחק איתי\", \"אני תמיד עושה טעויות\", ומצייר סביבו ענן.",
     "בדיקה במים (5 דק׳). כל ילד מניח את הענן בקערת מים, והדיו מתחיל להתפשט. המורה: \"מי יכול להגיד לי, הענן הזה אמיתי לגמרי? או שהוא כמו צבע במים, מתפשט, אבל לא נכון?\"",
