    "text": "שבו בנוחות. רגליים על הרצפה, ידיים על הירכיים. עצמו עיניים בעדינות.\n\n\"עכשיו נכווץ חלקים בגוף ואז נשחרר אותם, כדי להרגיש איך זה כששריר מתוח וכששריר רפוי.\"\n\nידיים, לימון לסחוט: \"דמיינו שיש לכם לימון ביד. סגרו חזק את כפות הידיים לאגרופים, סחטו את הלימון! עוד... עוד... ועכשיו שחררו, וזרקו את הלימון.\" שימו לב לתחושה בידיים, אולי חום או דגדוג קל.\n\nכתפיים, צב בשריון: \"הרימו את הכתפיים גבוה לכיוון האוזניים, כמו צב שמכניס את הראש לשריון... מחזיקים... ועכשיו, שחררו! הורידו את הכתפיים לגמרי.\"\n\nפנים, פרצוף חמוץ: \"כווצו את כל שרירי הפנים אל האף. עצמו עיניים חזק, קמטו את האף, כווצו את הפה, כאילו אכלתם לימון!\" חמש שניות. \"ועכשיו שחררו. פתחו עיניים ופה, הזיזו קצת את הלסת.\"\n\nבטן ורגליים, קרש מתוח: \"כווצו את הבטן חזק, מתחו את הרגליים... מחזיקים... ומשחררים! תנו לרגליים לנוח על הרצפה.\"\n\nכל כיווץ כחמש שניות, ואחרי כל שחרור כמה שניות להרגיש.\n\nבסיום: נשימה עמוקה, ומנערים קלות ידיים ורגליים.",
