    "text": "שבו בנוחות, רגליים על הרצפה, ידיים בחיק. אפשר להניח את הראש על הזרועות או להישען לאחור. עצמו עיניים לאט.\n\n\"עכשיו נעבור חלק אחרי חלק בגוף, מהאצבעות של הרגליים ועד הראש, ונבדוק איך כל מקום מרגיש. איפה שנרגיש מתח, ננסה להרפות.\"\n\nכפות הרגליים: \"תנו לתשומת הלב לרדת לקצות האצבעות ברגליים... מה אתם מרגישים שם? את הגרביים? את הנעל? את הרצפה? אמרו לרגליים: הגיע הזמן לנוח.\"\n\nהשוקיים והברכיים: \"עלו במחשבה אל השוקיים והברכיים. הן כפופות? מתוחות? רק שימו לב, ותנו גם להן לנוח.\"\n\nהירכיים: \"הן לוחצות על הכיסא? מרגישים את המשקל שלהן? שחררו גם אותן.\"\n\nהבטן והחזה: \"שימו לב אם הבטן מכווצת או רכה. קחו נשימה עמוקה אל תוך הבטן... ושחררו. עכשיו בית החזה. מרגישים איך הוא עולה ויורד עם הנשימה?\"\n\nהגב והכתפיים: \"שחררו את הגב לתנוחה שנוחה לו. ועכשיו הכתפיים, המקום שסוחב לפעמים תיק כבד. בשאיפה הרימו אותן קלות, ובנשיפה הורידו אותן לגמרי.\"\n\nהידיים: \"בדקו שהאצבעות לא קפוצות. פתחו את כפות הידיים. תנו לזרועות להיות כבדות.\"\n\nהצוואר: \"הזיזו לאט את הראש ימינה ושמאלה... והחזירו לאמצע. דמיינו שהצוואר הוא צינור רך.\"\n\nהפנים: \"המצח, העיניים, הלחיים, הפה. אם הגבות מכווצות, הרפו. אפשר לחייך חיוך קטן. תנו ללשון לנוח, ולא לקפוץ את הלסת.\"\n\n\"לבסוף, דמיינו מקלחת חמימה שיורדת מראש הראש, והם יורדים לאורך כל הגוף ושוטפים את שאריות המתח החוצה, אל הרצפה.\"\n\nכמה רגעים של שקט מוחלט. \"שימו לב איך זה מרגיש כשכל הגוף נינוח.\"\n\n\"הזיזו בעדינות את האצבעות... התמתחו קצת, כמו בבוקר... קחו שאיפה עמוקה, ובנשיפה פתחו לאט את העיניים.\""
