    "text": "שבו בתנוחה נוחה. אפשר לעצום עיניים, או להוריד את המבט. שימו לב לנשימות שלכם, ותנו לגוף להירגע לאט לאט.\n\nקחו כמה נשימות עמוקות. שאפו באיטיות פנימה, ונשפו באיטיות החוצה.\n\nהכרת הטוב ברגע הזה: הפנו את תשומת הלב לטוב שמסביבכם. דברים פשוטים: האוויר שאתם נושמים, האדמה שתומכת בגוף, הרגע שבו הגעתם ואתם כאן.\n\nשאלו את עצמכם: \"מה טוב בחיים שלי כרגע, על אף האתגרים?\" התמקדו בדברים הקטנים: הנשימה, חום הגוף, השקט.\n\nהכרת הטוב בעצמי: האם יש משהו בי שאני מכיר עליו תודה? כוח פנימי, תכונה שעוזרת לי, משהו קטן שעשיתי בשביל עצמי.\n\nהכרת הטוב לאחרים: חשבו על מישהו שאתם מעריכים. מה הוא עושה שגורם לכם להרגיש טוב?\n\nהכרת הטוב בעולם: רגע, אדם או משהו בטבע שמסב לכם תחושה טובה.\n\nנסיים: קחו שלוש נשימות עמוקות, ותנו לטוב שאספנו להישאר רגע בלב."
