   "what": "מדמיינים אדם שאומר לי \"אני סומך עליך\", ונושמים פנימה ביטחון",
   "layer": "כולם",
   "minutes": "8",
   "note": "במקור המדיטציה עוסקת במשפחה. כאן היא פתוחה לכל אדם שהילד בוחר, כי לא לכל ילד יש בית שמרגיש בטוח. תמיד אפשר להשאיר עיניים פקוחות ולהוריד את המבט לרצפה. אם עולה משהו מדאיג, לא מבררים מול הכיתה. מודים לילד, ממשיכים, ומעבירים להיועצת באותו יום. תמיד אפשר לבחור מקום או רגע מדומיין.",
