    "text": "מצאו מקום שבו נוח לשבת. אפשר לעצום עיניים, או להוריד את המבט. הרגישו את הגוף מתיישב, יציב ונינוח. אפשר להניח את הידיים על הברכיים.\n\nקחו נשימה עמוקה דרך האף, ונשפו לאט דרך הפה. עוד פעם. שימו לב איך הגוף מתרכך.\n\nדמיינו חדר חמים ובטוח. סביבכם אנשים שאתם סומכים עליהם: מהבית, מבית הספר, מכל מקום. אפשר גם דמות מדומיינת.\n\nעכשיו דמיינו שאחד מהם עומד לידכם ואומר במילים חמות וברורות: \"אני סומך עליך. אני מאמין בך.\" הרגישו את המילים נכנסות פנימה.\n\nבכל שאיפה, שאפו לתוך הלב תחושה של ביטחון. כל נשימה מזכירה: אני שייך, ומעריכים אותי בדיוק כמו שאני.\n\nלפני שמסיימים, תודה קטנה: על האמון שאני מקבל, ועל האמון שאני נותן.\n\nכשאתם מוכנים, פקחו לאט את העיניים, וקחו את תחושת האמון איתכם הלאה."
